[asy]
pair A,B,C,D,EE,F,G,H,WW,X,Y,Z;
WW = (0,0);
G = (0,sqrt(2));
H = G + (0,2);
X = H + (0,1+2*sqrt(2));
A = X + (1+2*sqrt(2),0);
B = A + (1,0);
Y = B + (sqrt(2), 0);
C = Y + (0,-sqrt(2));
D = C - (0,3);
Z = D - (0,2*sqrt(2));
EE = Z - (2*sqrt(2),0);
F = EE - (2,0);
draw(F--WW--X--Y--Z--F--G);
draw(H--A);
draw(B--C);
draw(D--EE);
label("$W$",WW,SW);
label("$G$",G,W);
label("$H$",H,W);
label("$X$",X,NW);
label("$A$",A,N);
label("$B$",B,N);
label("$Y$",Y,NE);
label("$C$",C,E);
label("$D$",D,E);
label("$Z$",Z,SE);
label("$E$",EE,S);
label("$F$",F,S);
[/asy]




